data=json.loads(TARGET.read_text())
for item in data['courses']:
    for i,q in enumerate(item['course']['questions']):
        fixed=FIXES.get((item['key'],i))
        if fixed:
            prompt,answers=fixed
            if prompt:q['prompt']=prompt
            order=[(j-i)%4 for j in range(4)]
            q['choices']=[answers[j] for j in order];q['correct_index']=order.index(0)
        if item['key']=='waiter-03-difficult' and i in DIFFICULT_EXPLANATIONS:
            q['explanation']=DIFFICULT_EXPLANATIONS[i]
        if item['key']=='admin-03-control' and i==20:
            q['explanation']='При неизменном среднем чеке выручка равна 2000 × число чеков. 30 чеков дают 60000 ₽, 36 — 72000 ₽. Это рост числа чеков, а не доказательство улучшения допродаж.'
        if item['key']=='hookah-01-bowls' and i==24:
            q['explanation']='При одинаковых c и ΔT энергия Q пропорциональна массе: 200 ÷ 150 ≈ 1,33. Время реального нагрева требует данных о мощности, передаче тепла, геометрии и потерях.'
        if item['key']=='cook-03-allergens' and i==14:
            q['explanation']='Whey — молочная сыворотка, содержащая молочные белки. FDA показывает связь whey с молоком в маркировке. Для ограничения проверяют действующий состав всего продукта.'
        if item['key']=='clean-05-equipment' and i==26:
            q['explanation']='Последовательные этапы требуют 15 + 25 + 20 + 10 = 70 минут. В окне 60 минут не хватает 10. Пропускать обязательный этап ради суммы нельзя.'
    if item['key'] in {'bar-02-classics','cook-03-allergens'}:
        for s in item['sources']:
            if s['url'] in {'https://iba-world.com/iba-cocktail/negroni/','https://iba-world.com/iba-cocktail/dry-martini/','https://www.fda.gov/consumers/consumer-updates/have-food-allergies-read-label'}:
                s['checked_at']='2026-10-27'
TARGET.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print('Second editorial pass applied:',len(FIXES),'question sets;',len(DIFFICULT_EXPLANATIONS),'explanations')
